/**
 * FR-3.2 "Chapter Summary Verification" — comprehension MCQs generated by
 * Gemini, since this genuinely requires reading comprehension no
 * deterministic rule can do. See README.md's AI usage policy: this is
 * grammar-free content, same category as summarize.ts, and every question
 * it produces must be labeled "AI-generated, unverified" same as the
 * summary/Fawā'id it's generated alongside.
 */

export interface ComprehensionQuestion {
  questionEn: string;
  options: string[];
  correctIndex: number;
  pageNumber?: number;
}

export const COMPREHENSION_RESPONSE_SCHEMA = {
  type: "object",
  properties: {
    questions: {
      type: "array",
      description: "3-5 multiple-choice comprehension questions testing understanding of the text below",
      items: {
        type: "object",
        properties: {
          questionEn: { type: "string" },
          options: { type: "array", items: { type: "string" }, description: "Exactly 4 options" },
          correctIndex: { type: "integer", description: "0-based index into options of the correct answer" },
          pageNumber: { type: "integer", description: "Page this question is grounded in, if applicable" },
        },
        required: ["questionEn", "options", "correctIndex"],
      },
    },
  },
  required: ["questions"],
};

export function buildComprehensionPrompt(title: string, documentText: string): string {
  return `You are writing a reading-comprehension quiz for a learner studying the Arabic-language text titled "${title}", based ONLY on the excerpt below (not general knowledge about the title).

Write 3-5 multiple-choice questions (4 options each, one correct) that test whether a reader actually understood the content, themes, or arguments of this specific text. Avoid trivial questions (e.g. "how many pages") — ask about substance. Every question and all four options must be answerable from the text below alone.

Text:
${documentText}`;
}
